using System;
using System.Collections.Generic;
using System.IO;
using GloomhavenVR.Core.SteamLink;
using UnityEditor;
using UnityEngine;
using Object=UnityEngine.Object;

public static class FullCoverageFixture
{
 [Serializable] private sealed class Row{public string name;public int carrier,partialSource,partialOld,partialFull;public float sourceWidth,oldWidth,fullWidth,sourceEdge,oldEdge,fullEdge,centerSource,centerOld,centerFull,rgbInteriorDelta,gradientDelta;}
 [Serializable] private sealed class Report{public bool passed;public string unity,device,backend,failure;public int checks,haloChecks,guardChecks;public float maxHaloError,maxGuardError,meanOldWidth,meanFullWidth,maxOldMotionError,maxFullMotionError;public List<Row> rows=new List<Row>();}
 private static readonly Report report=new Report();private static readonly List<Object> owned=new List<Object>();
 private static T Own<T>(T o)where T:Object{owned.Add(o);return o;}
 private static void Check(bool v,string why){report.checks++;if(!v)throw new Exception(why);}
 private static RenderTexture Rt(int w,int h,int depth=0,int aa=1){var r=Own(new RenderTexture(w,h,depth,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear));r.antiAliasing=aa;Check(r.Create(),"Actual target created");return r;}
 private static Texture2D Read(RenderTexture r){var old=RenderTexture.active;try{RenderTexture.active=r;var t=new Texture2D(r.width,r.height,TextureFormat.RGBA32,false,true);t.ReadPixels(new Rect(0,0,r.width,r.height),0,0,false);t.Apply();return t;}finally{RenderTexture.active=old;}}
 private static float Cross(Color32[] a,float level){for(int x=1;x<1024;x++){float p=a[1024*2048+x-1].a/255f,n=a[1024*2048+x].a/255f;if(p<=level&&n>=level&&n>p)return x-1+(level-p)/(n-p);}return -1;}
 private static float Width(Color32[] a,float amplitude){float l=Cross(a,amplitude*.1f),h=Cross(a,amplitude*.9f);return l<0||h<0?-1:h-l;}
 private static float LerpG(Color32[] p,int w,int h,float x,float y,bool alpha){x-=.5f;y-=.5f;int ix=Mathf.FloorToInt(x),iy=Mathf.FloorToInt(y);float fx=x-ix,fy=y-iy;Func<int,int,float> get=(xx,yy)=>{var c=p[Mathf.Clamp(yy,0,h-1)*w+Mathf.Clamp(xx,0,w-1)];return (alpha?c.a:c.g)/255f;};return Mathf.Lerp(Mathf.Lerp(get(ix,iy),get(ix+1,iy),fx),Mathf.Lerp(get(ix,iy+1),get(ix+1,iy+1),fx),fy);}
 private static Vector2 AtlasPoint(int tile,float x,float y){var origin=FullProfile.Origins[tile];return origin+(tile%2==0?new Vector2(x,y):new Vector2(y,2048-x));}
 private static float AtlasG(Color32[] pixels,int side,Vector2 point){return LerpG(pixels,side,side,point.x/3168*side,(1-point.y/3168)*side,false);}
 private static void InspectHalos(RenderTexture carrier,Color32[] source,string output,bool save)
 {
  var texture=Read(carrier);var pixels=texture.GetPixels32();int side=carrier.width;
  float haloInset=side==3168?.5f:1.5f;
  int[] codes=FullProfile.Codes;for(int i=0;i<12;i++){float v=AtlasG(pixels,side,FullProfile.GuardOrigin+Vector2.one*16+FullProfile.GuardStride*i);float e=Mathf.Abs(v-codes[i]/255f);report.maxGuardError=Mathf.Max(report.maxGuardError,e);report.guardChecks++;Check(e<1.1f/255,"Frozen guard cell exact "+i);}
  // Interior along the entire global X domain and both sides of every row seam.
  // The source profile separately proves non-overlapping halo rectangles.
  foreach(int tile in new[]{0,1,2,3})foreach(float x in new[]{-16+haloInset,-.5f,.5f,17.5f,511.5f,1023.5f,1535.5f,2030.5f,2047.5f,2048.5f,2064-haloInset})foreach(float y in new[]{-16+haloInset,-.5f,.5f,255.5f,511.5f,512.5f,528-haloInset}){
   var point=AtlasPoint(tile,x,y);float expected=LerpG(source,2048,2048,Mathf.Clamp(x,.5f,2047.5f),2048-Mathf.Clamp(tile*512+y,.5f,2047.5f),true);float actual=AtlasG(pixels,side,point);float error=Mathf.Abs(expected-actual);report.maxHaloError=Mathf.Max(report.maxHaloError,error);report.haloChecks++;Check(error<3.1f/255,"Global halo continuation/rotation tile="+tile+" x="+x+" y="+y+" expected="+expected+" actual="+actual);}
  if(save)File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(output),"full-atlas-"+side+".png"),texture.EncodeToPNG());Object.DestroyImmediate(texture);
 }
 private static Row Case(string name,Camera camera,SceneEyeOutput oldPack,SceneEyeOutput fullPack,RenderTexture oldCarrier,RenderTexture carrier,RenderTexture decoded,Material oldProbe,Material fullProbe,string output,float amplitude,bool save,bool inspect=false)
 {
  camera.Render();var sourceTexture=Read(camera.targetTexture);var source=sourceTexture.GetPixels32();Check(oldPack.TryRender(camera.targetTexture,oldCarrier,Camera.MonoOrStereoscopicEye.Left)==SceneEyeResult.Rendered,"Actual legacy producer");Check(fullPack.TryRender(camera.targetTexture,carrier,Camera.MonoOrStereoscopicEye.Left)==SceneEyeResult.Rendered,"Actual full producer");Graphics.Blit(oldCarrier,decoded,oldProbe);var oldTexture=Read(decoded);var old=oldTexture.GetPixels32();Graphics.Blit(carrier,decoded,fullProbe);var fullTexture=Read(decoded);var full=fullTexture.GetPixels32();
  var row=new Row{name=name,carrier=carrier.width,sourceWidth=Width(source,amplitude),oldWidth=Width(old,amplitude),fullWidth=Width(full,amplitude),sourceEdge=Cross(source,amplitude*.5f),oldEdge=Cross(old,amplitude*.5f),fullEdge=Cross(full,amplitude*.5f),centerSource=source[1024*2048+1024].a/255f,centerOld=old[1024*2048+1024].a/255f,centerFull=full[1024*2048+1024].a/255f};
  for(int x=0;x<2048;x++){float a=source[1024*2048+x].a/255f,b=old[1024*2048+x].a/255f,c=full[1024*2048+x].a/255f;if(a>.01f&&a<amplitude-.01f)row.partialSource++;if(b>.01f&&b<amplitude-.01f)row.partialOld++;if(c>.01f&&c<amplitude-.01f)row.partialFull++;}
  foreach(int y in new[]{700,1000,1300})foreach(int x in new[]{700,1000,1300}){int i=y*2048+x;row.rgbInteriorDelta=Mathf.Max(row.rgbInteriorDelta,Mathf.Max(Mathf.Abs(source[i].r-full[i].r),Mathf.Max(Mathf.Abs(source[i].g-full[i].g),Mathf.Abs(source[i].b-full[i].b)))/255f);row.gradientDelta=Mathf.Max(row.gradientDelta,Mathf.Abs(source[i].a-full[i].a)/255f);}
  Check(row.rgbInteriorDelta<2.1f/255,"Retain decoded contribution RGB interior "+name);Check(row.gradientDelta<2.1f/255,"Continuous alpha values retained "+name);
  if(save){File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(output),name+"-source.png"),sourceTexture.EncodeToPNG());File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(output),name+"-old-decoded.png"),oldTexture.EncodeToPNG());File.WriteAllBytes(Path.Combine(Path.GetDirectoryName(output),name+"-full-decoded.png"),fullTexture.EncodeToPNG());}
  if(inspect)InspectHalos(carrier,source,output,true);
  Object.DestroyImmediate(sourceTexture);Object.DestroyImmediate(oldTexture);Object.DestroyImmediate(fullTexture);report.rows.Add(row);return row;
 }
 public static void Start(){string[] args=Environment.GetCommandLineArgs();string output=args[Array.IndexOf(args,"-fullResult")+1];AssetBundle oldBank=null,fullBank=null;SceneEyeOutput oldPack=null,fullPack=null;SceneEyeCoverage coverage=null;int exit=1;try{
  report.unity=Application.unityVersion;report.device=SystemInfo.graphicsDeviceName;report.backend=SystemInfo.graphicsDeviceType.ToString();Check(report.unity=="2021.3.5f1"&&QualitySettings.activeColorSpace==ColorSpace.Gamma&&report.backend=="Vulkan","Actual Gamma Vulkan");oldBank=AssetBundle.LoadFromFile(args[Array.IndexOf(args,"-oldBank")+1]);Check(oldBank,"Frozen legacy shipping bank loaded");Shader oldShader=null,newShader=null,coverShader=null;foreach(var s in oldBank.LoadAllAssets<Shader>()){if(s.name==SceneAtlasProfile.ShaderName)oldShader=s;if(s.name==SceneEyeCoverage.ShaderName)coverShader=s;}if(Array.IndexOf(args,"-sameBank")>=0){fullBank=oldBank;oldBank=null;}else{oldBank.Unload(false);oldBank=null;fullBank=AssetBundle.LoadFromFile(args[Array.IndexOf(args,"-fullBank")+1]);}Check(fullBank,"Full shipping bank loaded or identical container reused");foreach(var s in fullBank.LoadAllAssets<Shader>())if(s.name==SceneAtlasProfile.FullShaderName)newShader=s;Check(oldShader&&newShader&&coverShader,"Actual old and full-res shaders");oldPack=new SceneEyeOutput(oldShader);fullPack=new SceneEyeOutput(newShader);coverage=new SceneEyeCoverage(coverShader);Check(fullPack.Profile=="scene-contribution-atlas-v2","Actual immutable v2 profile");
  var head=Own(new GameObject("Owned source camera"));var c=head.AddComponent<Camera>();c.enabled=false;c.orthographic=true;c.orthographicSize=1;c.transform.position=new Vector3(0,0,-4);c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.clear;c.allowHDR=false;c.renderingPath=RenderingPath.Forward;c.cullingMask=1<<30;c.nearClipPlane=.1f;c.farClipPlane=10;c.targetTexture=Rt(2048,2048,24);Check(coverage.Arm(c,1),"Actual unmodified same-eye coverage");var oldCarrier=Rt(3408,3408);var exact=Rt(3168,3168);var real=Rt(3408,3408);var decoded=Rt(2048,2048);var oldProbe=Own(new Material(Shader.Find("FullCoverageOwned/Probe")));oldProbe.SetFloat("_Legacy",1);var fullProbe=Own(new Material(Shader.Find("FullCoverageOwned/Probe")));for(int i=0;i<4;i++)fullProbe.SetVector("_Origin"+i,new Vector4(FullProfile.Origins[i].x,FullProfile.Origins[i].y,0,0));
  var quad=Own(GameObject.CreatePrimitive(PrimitiveType.Quad));quad.layer=30;quad.transform.localScale=new Vector3(1.2f,1.6f,1);var material=Own(new Material(Shader.Find("FullCoverageOwned/Surface")));quad.GetComponent<Renderer>().sharedMaterial=material;
  bool loaderOnly=Array.IndexOf(args,"-loaderOnly")>=0;if(loaderOnly){material.SetColor("_Color",new Color(.2f,.4f,.6f,1));var row=Case("same-bank-loader",c,oldPack,fullPack,oldCarrier,exact,decoded,oldProbe,fullProbe,output,1,false);Check(row.fullWidth<row.oldWidth-.5f,"Default same-bank legacy control and full producer remain distinct");}else{bool continuation=Array.IndexOf(args,"-continuation")>=0;
  if(!continuation){foreach(float alpha in new[]{.25f,.5f,.75f,1f}){material.SetColor("_Color",new Color(.2f,.4f,.6f,alpha));var row=Case("step-"+alpha,c,oldPack,fullPack,oldCarrier,exact,decoded,oldProbe,fullProbe,output,alpha,alpha==1);Check(Mathf.Abs(row.centerFull-alpha)<1.1f/255,"Unbacked glass opacity retained "+alpha);Check(row.fullWidth<row.oldWidth-.5f,"Full resolution materially sharpens non-window opacity step "+alpha);}
  foreach(float alpha in new[]{0f,.25f,.5f,.75f,1f}){quad.transform.localScale=new Vector3(2,2,1);material.SetColor("_Color",new Color(.2f,.4f,.6f,alpha));var row=Case("constant-"+alpha,c,oldPack,fullPack,oldCarrier,real,decoded,oldProbe,fullProbe,output,Mathf.Max(.01f,alpha),false);Check(Mathf.Abs(row.centerFull-alpha)<1.1f/255,"Constant glass remains numeric partial alpha "+alpha);}
  material.SetFloat("_Additive",1);material.SetColor("_Color",new Color(.2f,.4f,.6f,0));var additive=Case("additive-zero-alpha",c,oldPack,fullPack,oldCarrier,real,decoded,oldProbe,fullProbe,output,1,true);Check(additive.centerFull==0,"A0 remains A0");Check(additive.rgbInteriorDelta==0,"Additive contribution survives at A0 exactly");material.SetFloat("_Additive",0);material.SetColor("_Color",new Color(.2f,.4f,.6f,1));material.SetFloat("_Mode",2);
  Case("gradient-exact",c,oldPack,fullPack,oldCarrier,exact,decoded,oldProbe,fullProbe,output,1,true,true);}
  quad.transform.localScale=new Vector3(2,2,1);material.SetFloat("_Mode",2);material.SetColor("_Color",new Color(.2f,.4f,.6f,1));Case("gradient-carrier",c,oldPack,fullPack,oldCarrier,real,decoded,oldProbe,fullProbe,output,1,false,true);
  material.SetFloat("_Mode",0);quad.transform.localScale=new Vector3(1.2f,1.6f,1);float oldTotal=0,newTotal=0;int edges=0;
  c.targetTexture=Rt(2048,2048,24,4);Check(coverage.Arm(c,2),"Actual4xMSAA");for(int phase=0;phase<32;phase++){quad.transform.rotation=Quaternion.Euler(0,0,phase<16?0:17);quad.transform.position=new Vector3((phase%16)/16f*2/2048,0,0);var row=Case("motion-"+phase,c,oldPack,fullPack,oldCarrier,real,decoded,oldProbe,fullProbe,output,1,phase==0||phase==16);if(row.oldWidth>=0&&row.fullWidth>=0){oldTotal+=row.oldWidth;newTotal+=row.fullWidth;edges++;report.maxOldMotionError=Mathf.Max(report.maxOldMotionError,Mathf.Abs(row.oldEdge-row.sourceEdge));report.maxFullMotionError=Mathf.Max(report.maxFullMotionError,Mathf.Abs(row.fullEdge-row.sourceEdge));}}report.meanOldWidth=oldTotal/edges;report.meanFullWidth=newTotal/edges;Check(report.meanFullWidth<report.meanOldWidth-.5f,"32phase fullres edge improvement is material");
  quad.transform.rotation=Quaternion.Euler(0,0,17);quad.transform.localScale=new Vector3(.003f,1.6f,1);var thin=Case("thin-oblique",c,oldPack,fullPack,oldCarrier,real,decoded,oldProbe,fullProbe,output,1,true);Check(thin.partialFull>0,"Thin MSAA silhouette retains partial coverage instead of alpha threshold");}report.passed=true;exit=0;
 }catch(Exception e){report.failure=e.ToString();Debug.LogException(e);}finally{if(coverage!=null)coverage.Dispose();if(oldPack!=null)oldPack.Dispose();if(fullPack!=null)fullPack.Dispose();for(int i=owned.Count-1;i>=0;i--)if(owned[i])Object.DestroyImmediate(owned[i]);if(oldBank)oldBank.Unload(true);if(fullBank)fullBank.Unload(true);File.WriteAllText(output,JsonUtility.ToJson(report,true)+"\n");}EditorApplication.Exit(exit);}
}
